import {
  getActiveCompanyCode,
  getAuthUser,
  type SearchInputConfig,
} from '@linm-soft-org/linm-web-common-components';
import { createStaticLookupSearchConfig } from '../../../../../components/search';
import { apiClient, unwrap, type BffResponse } from '../../../../../services/api';
import type { PagedResult } from '../../../../../services/kt/models';

export interface CostCodeLookupItem {
  id: string;
  code: string;
  name: string;
  /** TK đối ứng mặc định từ ExpenseItem.AccountCode. */
  accountCode?: string;
  isActive?: boolean;
}

export interface CompanyCodeLookupItem {
  code: string;
  name: string;
  shortName?: string;
}

interface ExpenseItemApiRow {
  id: string;
  code: string;
  name: string;
  accountCode?: string | null;
  isActive?: boolean;
}

/**
 * Mã CP = ExpenseItem (Master) — không dùng FPC `/fpc/cost-codes`.
 * Remap IMP ghi `costCode` = ExpenseItem.Code (CP_DIEN, PHI_NH…).
 */
async function fetchExpenseCostCodes(): Promise<CostCodeLookupItem[]> {
  try {
    const res = await apiClient.get<BffResponse<PagedResult<ExpenseItemApiRow> | ExpenseItemApiRow[]>>(
      '/master/expense-items?page=1&pageSize=500',
    );
    const data = unwrap(res);
    const list = Array.isArray(data) ? data : (data?.items ?? []);
    return list
      .filter(c => c.isActive !== false)
      .map(c => ({
        id: c.id,
        code: c.code,
        name: c.name,
        accountCode: (c.accountCode || '').trim() || undefined,
        isActive: c.isActive,
      }));
  } catch {
    return [];
  }
}

export function createCostCodeSearchConfig(): SearchInputConfig<CostCodeLookupItem> {
  return createStaticLookupSearchConfig({
    loadItems: fetchExpenseCostCodes,
    getKey: c => c.id || c.code,
    getCode: c => c.code,
    getName: c => c.name,
    getFilterText: c => `${c.code} ${c.name}`,
    /** Single input: `CODE — Name` (PT/PC lines). IMP grid có thể override primaryDisplay. */
    getSingleDisplay: c => {
      const code = (c.code || '').trim();
      const name = (c.name || '').trim();
      if (code && name) return `${code} — ${name}`;
      return code || name;
    },
    codeHeaderLabel: 'Mã CP',
    nameHeaderLabel: 'Tên chi phí',
  });
}

interface ActiveCompanyApiItem {
  id: string;
  code?: string;
  name: string;
  shortName?: string;
}

async function fetchActiveCompanies(extraCodes: string[] = []): Promise<CompanyCodeLookupItem[]> {
  const byCode = new Map<string, CompanyCodeLookupItem>();

  const add = (code: string, name?: string, shortName?: string) => {
    const c = code.trim();
    if (!c) return;
    const key = c.toUpperCase();
    const existing = byCode.get(key);
    const label = (name || shortName || '').trim() || existing?.name || c;
    byCode.set(key, {
      code: existing?.code || c,
      name: label,
      shortName: shortName || existing?.shortName,
    });
  };

  try {
    const res = await apiClient.get<BffResponse<ActiveCompanyApiItem[]>>('/companies/active-list');
    for (const item of unwrap(res) ?? []) {
      const code = (item.code || item.id || '').trim();
      add(code, item.name, item.shortName);
    }
  } catch {
    // fallback below
  }

  const user = getAuthUser();
  const active = (getActiveCompanyCode() || '').trim();
  if (active) add(active);
  for (const c of user?.allowedCompanyCodes ?? []) add(c);
  const userCo = (user?.companyCode || '').trim();
  if (userCo) add(userCo);
  for (const c of extraCodes) add(c);

  return [...byCode.values()].sort((a, b) => a.code.localeCompare(b.code, 'vi'));
}

/** companyCode-only lookup — Short Code + Name · cấm Guid (Step 2tc). */
export function createCompanyCodeSearchConfig(
  extraCodes: string[] = [],
): SearchInputConfig<CompanyCodeLookupItem> {
  return createStaticLookupSearchConfig({
    loadItems: () => fetchActiveCompanies(extraCodes),
    getKey: c => c.code,
    getCode: c => c.code,
    getName: c => c.name || c.shortName || c.code,
    getFilterText: c => `${c.code} ${c.name} ${c.shortName ?? ''}`,
    getSingleDisplay: c => c.code,
    codeHeaderLabel: 'Mã ĐV',
    nameHeaderLabel: 'Tên đơn vị',
  });
}

/** Resolve map for primaryDisplay (code → name). */
export async function loadCompanyCodeMap(
  extraCodes: string[] = [],
): Promise<Map<string, CompanyCodeLookupItem>> {
  const list = await fetchActiveCompanies(extraCodes);
  const map = new Map<string, CompanyCodeLookupItem>();
  for (const c of list) {
    map.set(c.code, c);
    map.set(c.code.toUpperCase(), c);
  }
  return map;
}
